def done_flags(states, P, R):
    dn = []
    for st in states:
        ok = True
        dl = st["delivered"]
        for r in range(P):
            if len(dl[r]) != R:
                ok = False
                break
        dn.append(ok)
    return dn


def state_is_safe(st, expected, inp, P, R, D):
    dl = st["delivered"]
    for r in range(P):
        arr = dl[r]
        for q in range(len(arr)):
            if arr[q] != expected[q]:
                return False
    for s in st["slots"]:
        tot = [0] * D
        seq = s["seq"]
        for r in s["ranks"]:
            vec = inp[r][seq]
            for i in range(D):
                tot[i] += vec[i]
        if s["sum"] != tot:
            return False
    return True


def build_adj(edges, n, only_live=None):
    adj = [[] for _ in range(n)]
    for eid, (s, lab, t) in enumerate(edges):
        if only_live is not None:
            if not only_live[s] or not only_live[t]:
                continue
        adj[s].append((eid, t))
    return adj


def adj_plain(edges, n, live):
    adj = [[] for _ in range(n)]
    for eid, (s, lab, t) in enumerate(edges):
        if live[s] and live[t]:
            adj[s].append((eid, t))
    return adj


def bfs_path(start, adj, n, target_test):
    """returns (path_edge_ids, node) for first node satisfying target_test"""
    par = [-2] * n  # -2 unvisited
    pare = [0] * n
    par[start] = -1
    q = [start]
    qi = 0
    while qi < len(q):
        u = q[qi]
        qi += 1
        if target_test(u):
            path = []
            v = u
            while par[v] != -1:
                path.append(pare[v])
                v = par[v]
            path.reverse()
            return path, u
        for eid, t in adj[u]:
            if par[t] == -2:
                par[t] = u
                pare[t] = eid
                q.append(t)
    return None, None


def state_safety_check(states, expected, inp, P, R, D, edges, n, start):
    live = [True] * n
    adj = adj_plain(edges, n, live)
    res = bfs_path(start, adj, n, lambda u: not state_is_safe(states[u], expected, inp, P, R, D))
    return res
