def tarjan_subset(nodes, node_set, adj):
    """SCC of induced subgraph on members (all in node_set); returns list of lists."""
    idx = {}
    low = {}
    onst = set()
    stack = []
    comps = []
    for root in nodes:
        if root in idx:
            continue
        work = [[root, 0]]
        while work:
            fr = work[-1]
            v = fr[0]
            if fr[1] == 0:
                idx[v] = len(idx)
                low[v] = idx[v]
                stack.append(v)
                onst.add(v)
            recurse = False
            av = adj[v]
            ln = len(av)
            pi = fr[1]
            while pi < ln:
                w = av[pi]
                pi += 1
                if w in node_set:
                    if w not in idx:
                        fr[1] = pi
                        work.append([w, 0])
                        recurse = True
                        break
                    elif w in onst and idx[w] < low[v]:
                        low[v] = idx[w]
            if recurse:
                continue
            work.pop()
            if low[v] == idx[v]:
                comp = []
                while True:
                    w = stack.pop()
                    onst.discard(w)
                    comp.append(w)
                    if w == v:
                        break
                comps.append(comp)
            if work:
                u = work[-1][0]
                if low[v] < low[u]:
                    low[u] = low[v]
    return comps


def hierholzer(nodes_idx, adj_eid, adj_tgt, deg, edge_lookup, m_nodes_cnt):
    """adj_eid[u] list of edge ids; adj_tgt[u] parallel target ids."""
    tot = len(nodes_idx)
    ptr = [0] * tot
    stack = [nodes_idx[0]]
    popnodes = []
    while stack:
        u = stack[-1]
        if ptr[u] < deg[u]:
            stack.append(adj_tgt[u][ptr[u]])
            ptr[u] += 1
        else:
            popnodes.append(stack.pop())
    popnodes.reverse()
    out = []
    for i in range(len(popnodes) - 1):
        u = popnodes[i]
        v = popnodes[i + 1]
        out.append(edge_lookup[u][v].pop(0))
    return out


def compute_liveness(states, edges, fair, start, n, done, reach, P):
    weakb = [i for i in range(len(fair)) if fair[i][1] == "weak"]
    strongb = [i for i in range(len(fair)) if fair[i][1] == "strong"]
    DECL = (1 << len(fair)) - 1
    bit = {}
    for i, (a, m) in enumerate(fair):
        bit[a] = 1 << i
    live = [s for s in range(n) if reach[s] and not done[s]]
    if not live:
        return True, None
    enm_state = [0] * n
    for s, lab, t in edges:
        b = bit.get(lab)
        if b:
            enm_state[s] |= b
    idmap = {}
    for i, s in enumerate(live):
        idmap[s] = i
    k = len(live)
    adj = [[] for _ in range(k)]
    m_nodes = []
    for eid in range(len(edges)):
        s, lab, t = edges[eid]
        if s in idmap and t in idmap:
            b = bit.get(lab)
            if b is None:
                adj[idmap[s]].append(idmap[t])
            else:
                mid = len(adj)
                adj.append([])
                m_nodes.append((eid, b))
                adj[idmap[s]].append(mid)
                adj[mid].append(idmap[t])
    for i in range(k):
        adj[i].append(i)
    tot = len(adj)
    enmask = [0] * tot
    mmask = [0] * tot
    ymask = [0] * tot
    for i in range(k):
        s = live[i]
        enmask[i] = enm_state[s]
        ymask[i] = (~enm_state[s]) & DECL
    for j, (eid, b) in enumerate(m_nodes):
        nd = k + j
        ymask[nd] = b
        mmask[nd] = b

    allnodes = list(range(tot))
    alltset = set(allnodes)
    comps = tarjan_subset(allnodes, alltset, adj)
    members = [c for c in comps]
    work = list(range(len(members)))
    active = [True] * len(members)
    result_comp = None
    while work:
        c = work.pop()
        if not active[c]:
            continue
        mem = members[c]
        orE = 0
        orM = 0
        orY = 0
        for v in mem:
            orE |= enmask[v]
            orM |= mmask[v]
            orY |= ymask[v]
        rm = None
        for a in weakb:
            if not ((orY >> a) & 1):
                rm = mem
                break
        if rm is None:
            for a in strongb:
                if ((orE >> a) & 1) and not ((orM >> a) & 1):
                    bb = 1 << a
                    rm = [v for v in mem if enmask[v] & bb]
                    break
        if rm is None:
            result_comp = mem
            break
        active[c] = False
        if len(rm) == len(mem):
            continue
        rmset = set(rm)
        rem = [v for v in mem if v not in rmset]
        newc = tarjan_subset(rem, set(rem), adj)
        for nc in newc:
            members.append(nc)
            active.append(True)
            work.append(len(members) - 1)

    if result_comp is None:
        return True, None
    cprot = set()
    for v in result_comp:
        if v < k:
            cprot.add(live[v])
    lenv = cprot.__len__
    adjp = [[] for _ in range(n)]
    for eid in range(len(edges)):
        s, lab, t = edges[eid]
        if s in cprot and t in cprot:
            adjp[s].append((eid, t))
    path, tgt = bfs_path(start, adjp, n, lambda u: u in cprot)
    if path is None:
        return True, None
    # closed walk on protocol subgraph of cprot from tgt
    oid = {}
    for s in cprot:
        oid[s] = len(oid)
    sub_eid = []
    sub_u = []
    sub_v = []
    for s in cprot:
        for eid, t in adjp[s]:
            sub_eid.append(eid)
            sub_u.append(oid[s])
            sub_v.append(oid[t])
    nc = len(oid)
    outdeg = [0] * nc
    indeg = [0] * nc
    for u in sub_u:
        outdeg[u] += 1
    for v in sub_v:
        indeg[v] += 1
    nsub = len(sub_eid)
    adj_eid = [[] for _ in range(nc)]
    adj_tgt = [[] for _ in range(nc)]
    for z in range(nsub):
        adj_eid[sub_u[z]].append(sub_eid[z])
        adj_tgt[sub_u[z]].append(sub_v[z])
    lookup = [dict() for _ in range(nc)]
    for z in range(nsub):
        for _ in range(2):
            lookup[sub_u[z]].setdefault(sub_v[z], []).append(sub_eid[z])
    deg = [0] * nc
    for u in range(nc):
        deg[u] = len(adj_eid[u]) * 2
    if nsub == 0:
        loop = [-1]
    else:
        loop = hierholzer(list(oid.values()), adj_eid, adj_tgt, deg, lookup, nsub)
    return False, (path, loop)
