def parse_json_line(b):
    try:
        text = b.decode("utf-8")
    except Exception:
        raise Err("E_JSON")

    def const_bad(c):
        raise Err("E_JSON")

    def hook(pairs):
        d = {}
        for k, v in pairs:
            if k in d:
                raise Err("E_JSON")
            d[k] = v
        return d

    try:
        return json.loads(text, parse_constant=const_bad, object_pairs_hook=hook)
    except Err:
        raise
    except Exception:
        raise Err("E_JSON")


def handle(req):
    if not isinstance(req, dict):
