    if len(v) < 1 or len(v) > 12000:

    if len(v) < 1 or len(v) > 12000:
        raise Err("E_LIMIT")
    for f in v:
        keys = list(f.keys()) if isinstance(f, dict) else None
        if keys is None or len(keys) != 2 or "delivered" not in f or "slots" not in f:
            raise Err("E_SCHEMA")
        dl = f["delivered"]
        if type(dl) is not list:
            raise Err("E_SCHEMA")
        if len(dl) != P:
            raise Err("E_SCHEMA")
        for rank in dl:
            if type(rank) is not list:
                raise Err("E_SCHEMA")
            if len(rank) > R:
                raise Err("E_LIMIT")
            for vec in rank:
                if type(vec) is not list:
                    raise Err("E_SCHEMA")
                if len(vec) != D:
                    raise Err("E_SCHEMA")
                if vec:
                    if not all(type(x) is int for x in vec):
                        raise Err("E_SCHEMA")
                    if min(vec) < -VMAX_SNAP or max(vec) > VMAX_SNAP:
                        raise Err("E_LIMIT")
        sl = f["slots"]
        if type(sl) is not list:
            raise Err("E_SCHEMA")
        if len(sl) > 16:
            raise Err("E_LIMIT")
        seqs = set()
        for s in sl:
            ks = list(s.keys()) if isinstance(s, dict) else None
            if ks is None or len(ks) != 3 or "seq" not in s or "ranks" not in s or "sum" not in s:
                raise Err("E_SCHEMA")
            if type(s["seq"]) is not int:
                raise Err("E_SCHEMA")
            if not 0 <= s["seq"] < R:
                raise Err("E_LIMIT")
            if s["seq"] in seqs:
                raise Err("E_SCHEMA")
            seqs.add(s["seq"])
            rk = s["ranks"]
            if type(rk) is not list:
                raise Err("E_SCHEMA")
            rkset = set()
            for x in rk:
                if type(x) is not int:
                    raise Err("E_SCHEMA")
                if not 0 <= x < P:
                    raise Err("E_LIMIT")
                if x in rkset:
