def parse_json_line(b):
    try:
        text = b.decode("utf-8")
    except Exception:
        raise Err("E_JSON")

    def const_bad(c):
        raise Err("E_JSON")

    def hook(pairs):
        d = {}
        for k, v in pairs:
            if k in d:
                raise Err("E_JSON")
            d[k] = v
        return d

    def flt(s):
        f = float(s)
        if not math.isfinite(f):
            raise Err("E_JSON")
        return f

    try:
        return json.loads(text, parse_constant=const_bad, parse_float=flt,
                          object_pairs_hook=hook)
    except Err:
        raise
    except Exception:
        raise Err("E_JSON")


def handle(req):
    if not isinstance(req, dict):
        raise Err("E_SCHEMA")
    op = req.get("op")
    if not isinstance(op, str) or op not in ("replay", "audit", "export"):
        raise Err("E_SCHEMA")
    if op == "replay":
        check_keys(req, ("op", "inputs", "slots", "window", "events"))
        P, R, D, inp = parse_inputs(req["inputs"])
        return do_replay(inp, P, R, D, req)
    if op == "audit":
        check_keys(req, ("op", "inputs", "states", "edges", "start", "fairness"))
        P, R, D, inp = parse_inputs(req["inputs"])
        return do_audit(inp, P, R, D, req)
    check_keys(req, ("op", "inputs", "states", "edges", "start", "fairness"))
    P, R, D, inp = parse_inputs(req["inputs"])
    return do_export(inp, P, R, D, req)


